def hasMatch(s: str, p: str) -> bool:
    prefix, suffix = p.split('*')
    prefix_length = len(prefix)
    suffix_length = len(suffix)

    for i in range(len(s) - prefix_length + 1):
        if s.startswith(prefix, i):
            # Check if the suffix can be found after the prefix including potential overlaps
            if s[i + prefix_length:].find(suffix) != -1:
                return True
    return False

