from math import gcd


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_len = 0

    for i in range(n):
        prod = 1
        current_gcd = nums[i]
        current_lcm = nums[i]

        for j in range(i, n):
            prod *= nums[j]
            current_gcd = gcd(current_gcd, nums[j])
            current_lcm = lcm(current_lcm, nums[j])

            if prod == current_gcd * current_lcm:
                max_len = max(max_len, j - i + 1)

    return max_len

