def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations
    even_numbers = set()
    # Generate all permutations of the digits taken 3 at a time
    for perm in permutations(digits, 3):
        # Check if the last digit is even and the first is not zero
        if perm[2] % 2 == 0 and perm[0] != 0:
            even_numbers.add(perm)
    return len(even_numbers)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    max_cells = n * n
    max_containers_by_weight = maxWeight // w
    return min(max_cells, max_containers_by_weight)

def reverseDegree(s: str) -> int:
    reverse_alpha_position = {chr(i): 26 - (i - 97) for i in range(97, 123)}
    return sum(reverse_alpha_position[char] * (index + 1) for index, char in enumerate(s))

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)

    for i in range(len(s)):
        if marked[i]:
            continue
        mirror = chr(ord('z') - (ord(s[i]) - ord('a')))
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror:
                marked[i] = marked[j] = True
                score += (i - j)
                break
    return score

