def minCost(n: int, cost: List[List[int]]) -> int:
    # Dynamic programming table to store the minimum costs
    dp = [[0] * 3 for _ in range(n)]

    # Base case: first house costs directly from the cost array
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp table for each house
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = min(
                dp[i - 1][(j + 1) % 3],
                dp[i - 1][(j + 2) % 3]
            ) + cost[i][j]

    # Now handle the symmetry constraints
    min_cost = float('inf')

    # Check color combinations for the first half vs second half
    for first_color in range(3):
        for second_color in range(3):
            if first_color == second_color:
                continue
            current_cost = 0
            valid = True

            for i in range(n // 2):
                house_color = first_color if i % 2 == 0 else second_color
                current_cost += cost[i][house_color]
            for i in range(n // 2, n):
                house_color = first_color if (i - n) % 2 == 0 else second_color
                current_cost += cost[i][house_color]

            if valid:
                min_cost = min(min_cost, current_cost)

    return min_cost

