def maxFrequency(nums: List[int], k: int) -> int:
    initial_freq_k = nums.count(k)
    max_gain = 0
    n = len(nums)
    for v in range(1, 51):  # Since nums[i] and k are in the range 1 to 50
        if v == k:
            continue
        gain_array = [0] * n
        for i in range(n):
            if nums[i] == v:
                gain_array[i] = 1
            elif nums[i] == k:
                gain_array[i] = -1
        # Find maximum subarray sum using Kadane's algorithm
        current_sum = 0
        for value in gain_array:
            current_sum += value
            if current_sum < 0:
                current_sum = 0
            max_gain = max(max_gain, current_sum)
    return initial_freq_k + max(0, max_gain)

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    # Walk through each move and calculate maximum distance
    for move in s:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1

        # Calculate current distance
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)

    # Calculate overall potential distance with allowed changes
    total_moves = len(s)
    changes_possible = min(k, total_moves)
    if changes_possible > 0:
        max_distance = max(max_distance, current_distance + 2 * changes_possible)

    # Return the maximum possible Manhattan distance
    return max_distance
